import React, { useState } from 'react';
import { 
  Calendar, MapPin, Truck, User, 
  PlayCircle, CheckCircle2, AlertCircle, 
  ChevronRight, ArrowLeft, Info
} from 'lucide-react';

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState('schedule');
  const [selectedReport, setSelectedReport] = useState(null);
  const [jobDone, setJobDone] = useState(false);

  // Mock Data
  const schedule = [
    { id: 101, time: "08:00", area: "ZONE_A", task: "Routine Pick", status: "Done" },
    { id: 102, time: "10:30", area: "ZONE_C", task: "Citizen Report", status: "Alert", hasReport: true },
    { id: 103, time: "14:00", area: "ZONE_B", task: "Bulk Disposal", status: "Pending" },
  ];

  const reportDetails = {
    id: "REP_992",
    category: "Overflowing Bin",
    citizen: "John Doe",
    location: "Sector 7, Near Metro",
    desc: "The bin has been full for 2 days. Bad smell in the area."
  };

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex flex-col overflow-hidden">

      {/* --- TOP APP BAR --- */}
      <div className="p-6 pt-12 flex justify-between items-end bg-white/40 backdrop-blur-xl border-b-2 border-[#47510B]/5">
        <div>
          <h1 className="text-3xl font-black text-[#47510B] uppercase italic leading-none">
            {activeTab === 'reports' ? 'Field_Reports' : activeTab}
          </h1>
          <div className="flex items-center gap-2 mt-1">
            <div className="w-2 h-2 bg-[#CAD23C] rounded-full animate-pulse" />
            <span className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-[0.2em]">Live_Sync_Active</span>
          </div>
        </div>
        <div className="text-right">
             <span className="text-[10px] font-black text-[#AB1717] block uppercase italic">Unit_7729</span>
             <span className="text-[10px] font-black text-[#47510B] block">Sector_04</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 pb-32 custom-scrollbar">

        {/* TAB 1: SCHEDULE */}
        {activeTab === 'schedule' && (
          <div className="animate-slide-up space-y-4">
            {schedule.map((item) => (
              <div key={item.id} className={`p-5 rounded-[35px] border-2 border-[#47510B] shadow-[6px_6px_0_0_#47510B] flex justify-between items-center transition-all ${item.hasReport ? 'bg-[#FFB6A9]' : 'bg-white'}`}>
                <div>
                  <span className="text-[10px] font-black opacity-40 italic">{item.time} // {item.area}</span>
                  <h3 className="text-xl font-black text-[#47510B] uppercase">{item.task}</h3>
                </div>
                {item.hasReport ? (
                  <button onClick={() => setActiveTab('reports')} className="bg-[#AB1717] text-white p-3 rounded-2xl animate-bounce">
                    <AlertCircle size={20} />
                  </button>
                ) : (
                  <div className="opacity-20"><CheckCircle2 size={24} /></div>
                )}
              </div>
            ))}
          </div>
        )}

        {/* TAB 2: REPORTS (View and Resolve) */}
        {activeTab === 'reports' && (
          <div className="animate-slide-up space-y-6">
            <div className="p-8 bg-[#AB1717] text-white rounded-[40px] shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                    <span className="bg-white/20 px-3 py-1 rounded-full text-[10px] font-black uppercase">Category: {reportDetails.category}</span>
                    <h2 className="text-3xl font-black uppercase italic mt-4">{reportDetails.location}</h2>
                    <p className="mt-4 text-sm font-bold opacity-80 leading-relaxed italic">"{reportDetails.desc}"</p>
                    <button className="mt-8 w-full bg-[#FDFAD8] text-[#AB1717] py-4 rounded-2xl font-black uppercase text-xl shadow-[0_6px_0_0_#A1AED1]">
                        Mark Resolved
                    </button>
                </div>
                <Info size={140} className="absolute -right-10 -bottom-10 opacity-10 rotate-12" />
            </div>
          </div>
        )}

        {/* TAB 3: PICKUPS / DASHBOARD */}
        {activeTab === 'pickups' && (
          <div className="animate-slide-up space-y-6">
            <div className="bg-[#47510B] p-8 rounded-[40px] text-[#CAD23C] relative overflow-hidden group">
                <span className="text-[10px] font-black uppercase tracking-widest opacity-50">Current_Mission</span>
                <h2 className="text-4xl font-black italic uppercase leading-none mt-2">SECTOR_C<br/>GRID_9</h2>

                <div className="mt-8 flex gap-4">
                    <button className="flex-1 bg-[#CAD23C] text-[#47510B] py-4 rounded-2xl font-black uppercase text-sm active:scale-95 transition-transform">
                        GPS Route
                    </button>
                    <button 
                        onClick={() => setJobDone(!jobDone)}
                        className={`flex-1 py-4 rounded-2xl font-black uppercase text-sm border-2 transition-all
                        ${jobDone ? 'bg-green-500 border-transparent text-white' : 'bg-transparent border-[#CAD23C]'}`}>
                        {jobDone ? 'Verified ✓' : 'Mark Done'}
                    </button>
                </div>
            </div>

            {/* Admin Verification Logic Display */}
            <div className="p-6 bg-white border-4 border-[#47510B] rounded-[40px] relative">
                <div className="animate-scan h-[1px] top-1/2" />
                <h4 className="font-black text-[#47510B] uppercase text-xs mb-4">Live_Bin_Sensor_Data</h4>
                <div className="flex items-center justify-between font-black text-2xl italic">
                    <span>94%</span>
                    <span className="text-[10px] opacity-40 uppercase">Critical_Level</span>
                </div>
            </div>
          </div>
        )}

        {/* TAB 4: TRAINING & PROFILE (Integrated as requested) */}
        {activeTab === 'profile' && (
          <div className="animate-slide-up space-y-8">
            {/* Training Section */}
            <div className="p-6 bg-[#A1AED1] rounded-[40px] border-2 border-[#47510B]">
                <div className="flex items-center gap-3 mb-4">
                    <PlayCircle className="text-[#47510B]" />
                    <h3 className="font-black text-[#47510B] uppercase tracking-widest text-xs">Worker_Onboarding</h3>
                </div>
                <div className="aspect-video bg-[#47510B] rounded-[25px] flex items-center justify-center overflow-hidden relative">
                    <div className="w-16 h-16 bg-[#CAD23C] rounded-full flex items-center justify-center cursor-pointer hover:scale-110 transition-transform">
                        <PlayCircle size={32} />
                    </div>
                </div>
            </div>

            {/* Profile Section (Read Only) */}
            <div className="p-6 bg-white rounded-[40px] border-4 border-[#47510B] shadow-[10px_10px_0_0_#CAD23C]">
                <h3 className="font-black text-[#47510B] uppercase italic mb-6">Profile_Data</h3>
                <div className="space-y-4 text-xs font-bold uppercase">
                    <div className="border-b border-[#47510B]/10 pb-2">
                        <span className="opacity-40 block">Name</span> <span>Marcus Sterling</span>
                    </div>
                    <div className="border-b border-[#47510B]/10 pb-2">
                        <span className="opacity-40 block">Assigned_Truck</span> <span>T2T_TRUCK_88</span>
                    </div>
                    <div className="border-b border-[#47510B]/10 pb-2">
                        <span className="opacity-40 block">Performance_Rating</span> <span className="text-[#47510B]">A+</span>
                    </div>
                </div>
                <div className="mt-8 p-4 bg-[#FDFAD8] rounded-2xl text-center font-black text-[10px] text-[#AB1717]">
                    NO_EDIT_ACCESS_GRANTED_BY_ADMIN
                </div>
            </div>
          </div>
        )}

      </div>

      {/* --- FLOATING APPLE DOCK --- */}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[92%] max-w-[450px]">
        <div className="bg-[#47510B] p-2 rounded-[35px] flex justify-between items-center shadow-2xl border-t border-white/10">
          {[
            { id: 'schedule', icon: <Calendar size={20}/>, label: 'Schedule' },
            { id: 'pickups', icon: <Truck size={20}/>, label: 'Pickups' },
            { id: 'reports', icon: <AlertCircle size={20}/>, label: 'Reports' },
            { id: 'profile', icon: <User size={20}/>, label: 'Profile' },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-1 flex flex-col items-center gap-1 py-3 rounded-[28px] transition-all duration-300
                ${activeTab === tab.id ? 'bg-[#CAD23C] text-[#47510B] scale-105 shadow-inner' : 'text-white/40'}`}
            >
              {tab.icon}
              <span className="text-[8px] font-black uppercase tracking-tighter">{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

    </div>
  );
};

export default WorkerDashboard;
